import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage, onLogoutClick, role = 'student' }) {
  
  // Role එක අනුව Sidebar එකේ පෙන්විය යුතු Menu Items
  const getMenuItems = () => {
    switch (role) {
      case 'admin':
        return [
          { id: 'dashboard', label: 'Dashboard', icon: '📊' },
          { id: 'teachers', label: 'Teachers', icon: '👨‍🏫' },
          { id: 'students', label: 'Students', icon: '🎓' },
          { id: 'subjects', label: 'Subjects', icon: '📚' },
          { id: 'timetable', label: 'Timetable', icon: '🗓️' },
          { id: 'reports', label: 'Reports', icon: '📈' },
          { id: 'settings', label: 'Settings', icon: '⚙️' },
        ];
      case 'teacher':
        return [
          { id: 'dashboard', label: 'Dashboard', icon: '📊' },
          { id: 'materials', label: 'Study Materials', icon: '📁' },
          { id: 'activities', label: 'Activities', icon: '📝' },
          { id: 'question-bank', label: 'Question Bank', icon: '🏦' },
          { id: 'exams', label: 'Exams / Quizzes', icon: '✍️' },
          { id: 'timetable', label: 'Timetable', icon: '🗓️' },
          { id: 'settings', label: 'Profile Settings', icon: '⚙️' },
        ];
      case 'student':
      default:
        return [
          { id: 'dashboard', label: 'Dashboard', icon: '📊' },
          { id: 'materials', label: 'Study Materials', icon: '📖' },
          { id: 'activities', label: 'Activities', icon: '🧩' },
          { id: 'exams', label: 'Exams & Tests', icon: '📝' },
          { id: 'timetable', label: 'Timetable', icon: '🗓️' },
          { id: 'feedback', label: 'Feedback & Support', icon: '💬' },
          { id: 'settings', label: 'Profile Settings', icon: '⚙️' },
        ];
    }
  };

  const menuItems = getMenuItems();

  return (
    <aside style={styles.sidebar}>
      {/* Brand Logo / Header */}
      <div style={styles.logoContainer}>
        <div style={styles.logoIcon}>🖊️</div>
        <div>
          <h2 style={styles.logoText}>AuraPen</h2>
          <span style={styles.roleBadge}>{role.toUpperCase()} PORTAL</span>
        </div>
      </div>

      <hr style={styles.divider} />

      {/* Navigation Links */}
      <nav style={styles.nav}>
        {menuItems.map((item) => {
          const isActive = currentSubPage === item.id;
          return (
            <button
              key={item.id}
              onClick={() => setCurrentSubPage(item.id)}
              style={{
                ...styles.navBtn,
                ...(isActive ? styles.activeNavBtn : {}),
              }}
            >
              <span style={styles.icon}>{item.icon}</span>
              <span style={styles.label}>{item.label}</span>
            </button>
          );
        })}
      </nav>

      {/* Logout Button at Bottom */}
      <div style={styles.bottomSection}>
        <button onClick={onLogoutClick} style={styles.logoutBtn}>
          <span style={styles.icon}>🚪</span>
          <span style={styles.label}>Logout</span>
        </button>
      </div>
    </aside>
  );
}

const styles = {
  sidebar: {
    width: '260px',
    height: '100vh',
    backgroundColor: '#0f172a', // Dark slate theme
    color: '#f8fafc',
    display: 'flex',
    flexDirection: 'column',
    padding: '20px 16px',
    boxSizing: 'border-box',
    borderRight: '1px solid #1e293b',
    flexShrink: 0,
  },
  logoContainer: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    padding: '8px 4px',
  },
  logoIcon: {
    fontSize: '28px',
    backgroundColor: '#145c2e',
    width: '44px',
    height: '44px',
    borderRadius: '10px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  },
  logoText: {
    margin: 0,
    fontSize: '20px',
    fontWeight: 'bold',
    color: '#ffffff',
    letterSpacing: '0.5px',
  },
  roleBadge: {
    fontSize: '10px',
    fontWeight: '700',
    color: '#4ade80',
    letterSpacing: '1px',
  },
  divider: {
    borderColor: '#334155',
    margin: '18px 0',
    borderStyle: 'solid',
    borderWidth: '0.5px',
  },
  nav: {
    display: 'flex',
    flexDirection: 'column',
    gap: '6px',
    flex: 1,
    overflowY: 'auto',
  },
  navBtn: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    padding: '12px 16px',
    borderRadius: '10px',
    border: 'none',
    backgroundColor: 'transparent',
    color: '#94a3b8',
    fontSize: '14.5px',
    fontWeight: '500',
    cursor: 'pointer',
    textAlign: 'left',
    transition: 'all 0.2s ease-in-out',
  },
  activeNavBtn: {
    backgroundColor: '#145c2e',
    color: '#ffffff',
    fontWeight: '600',
    boxShadow: '0 4px 12px rgba(20, 92, 46, 0.3)',
  },
  icon: {
    fontSize: '18px',
  },
  label: {
    fontSize: '14px',
  },
  bottomSection: {
    paddingTop: '16px',
    borderTop: '1px solid #1e293b',
  },
  logoutBtn: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    width: '100%',
    padding: '12px 16px',
    borderRadius: '10px',
    border: 'none',
    backgroundColor: 'rgba(239, 68, 68, 0.1)',
    color: '#f87171',
    fontSize: '14.5px',
    fontWeight: '600',
    cursor: 'pointer',
    transition: 'all 0.2s ease',
  },
};
